import { z } from 'zod';
import { QueueItemSchema, IdeaSchema, ClaimIdeaResponseSchema, type QueueItem, type Idea, type IdeaStatus, type ClaimIdeaResponse } from '@utmessa/shared';
import {
  IntakeNetworkError,
  IntakeAuthError,
  IntakeAPIError,
  IntakeValidationError,
  IdeaAlreadyClaimedError,
  IdeaNotFoundError,
  IntakeUnavailableError,
} from '../errors/index.js';
import { createLogger } from '../utils/index.js';
import type { IntakeClientConfig, IIntakeClient } from '../types/index.js';

const logger = createLogger('IntakeClient');

/**
 * HTTP client for communicating with the Intake API
 *
 * Handles:
 * - Authentication via X-ORCH-KEY header
 * - Request timeout
 * - Response validation with partial recovery
 * - Error classification (network, auth, API, validation)
 */
export class IntakeClient implements IIntakeClient {
  private readonly baseUrl: string;
  private readonly apiKey: string;
  private readonly timeout: number;

  constructor(config: IntakeClientConfig) {
    this.baseUrl = config.baseUrl.replace(/\/$/, ''); // Remove trailing slash
    this.apiKey = config.apiKey;
    this.timeout = config.timeout;
  }

  /**
   * Fetch ideas from Intake API filtered by statuses
   *
   * @param statuses - Array of statuses to filter by
   * @returns Promise resolving to array of valid queue items (QueueItem, not full Idea)
   * @throws IntakeNetworkError on network failure
   * @throws IntakeAuthError on 401/403
   * @throws IntakeAPIError on other HTTP errors
   * @throws IntakeValidationError on invalid response schema
   */
  async fetchIdeas(statuses: IdeaStatus[]): Promise<QueueItem[]> {
    const statusParam = statuses.join(',');
    const url = `${this.baseUrl}/api/ideas?status=${encodeURIComponent(statusParam)}`;

    logger.debug({ url, statuses }, 'Fetching ideas from Intake API');

    try {
      const response = await fetch(url, {
        method: 'GET',
        headers: {
          'X-ORCH-KEY': this.apiKey,
          Accept: 'application/json',
        },
        signal: AbortSignal.timeout(this.timeout),
      });

      // Handle HTTP errors
      if (!response.ok) {
        const body = await this.safeParseBody(response);

        if (response.status === 401 || response.status === 403) {
          logger.warn(
            { status: response.status },
            'Authentication failed with Intake API'
          );
          throw new IntakeAuthError(
            `Authentication failed: ${response.statusText}`,
            response.status as 401 | 403
          );
        }

        logger.error(
          { status: response.status, body },
          'Intake API returned error'
        );
        throw new IntakeAPIError(
          `Intake API error: ${response.status} ${response.statusText}`,
          response.status,
          body
        );
      }

      // Parse successful response
      const json: unknown = await response.json();
      logger.debug({ responseType: typeof json }, 'Received response from Intake API');

      // Validate and return queue items
      const queueItems = this.validateQueueItems(json);
      logger.info({ count: queueItems.length }, 'Successfully fetched queue items');

      return queueItems;
    } catch (error) {
      // Re-throw our custom errors
      if (
        error instanceof IntakeNetworkError ||
        error instanceof IntakeAuthError ||
        error instanceof IntakeAPIError ||
        error instanceof IntakeValidationError
      ) {
        throw error;
      }

      // Convert fetch errors to IntakeNetworkError
      if (error instanceof Error) {
        if (error.name === 'TimeoutError' || error.name === 'AbortError') {
          logger.warn({ timeout: this.timeout }, 'Request timed out');
          throw new IntakeNetworkError(
            `Request timed out after ${this.timeout}ms`,
            error
          );
        }

        logger.error({ error: error.message }, 'Network error during fetch');
        throw new IntakeNetworkError(`Network error: ${error.message}`, error);
      }

      // Unknown error type
      throw new IntakeNetworkError('Unknown network error');
    }
  }

  /**
   * Safely parse response body as JSON
   */
  private async safeParseBody(response: Response): Promise<unknown> {
    try {
      return await response.json();
    } catch {
      return undefined;
    }
  }

  /**
   * Validate queue items array with partial recovery
   *
   * If the full array validation fails, attempts to validate each item
   * individually and returns valid items. Only throws if no valid items found.
   * 
   * Note: Intake API returns QueueItem[] (not full Idea[]) which excludes
   * sensitive fields like token and email.
   */
  private validateQueueItems(data: unknown): QueueItem[] {
    // First, ensure we have an array-like response
    if (!this.isIdeasResponse(data)) {
      logger.error(
        { responseType: typeof data },
        'Response is not in expected format'
      );
      throw new IntakeValidationError('Response is not in expected format', [
        { path: 'root', message: 'Expected object with ideas array' },
      ]);
    }

    const items = data.ideas;

    // Handle empty array (no ideas in queue)
    if (items.length === 0) {
      logger.debug('Empty queue response (no ideas)');
      return [];
    }

    // Fast path: try validating the whole array
    const arraySchema = z.array(QueueItemSchema);
    const fullResult = arraySchema.safeParse(items);

    if (fullResult.success) {
      return fullResult.data;
    }

    // Slow path: validate each item individually for partial recovery
    logger.warn(
      { errorCount: fullResult.error.errors.length },
      'Full validation failed, attempting partial recovery'
    );

    const validItems: QueueItem[] = [];
    const validationErrors: Array<{ path: string; message: string }> = [];

    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      const result = QueueItemSchema.safeParse(item);

      if (result.success) {
        validItems.push(result.data);
      } else {
        const errors = result.error.errors.map((e) => ({
          path: `ideas[${i}].${e.path.join('.')}`,
          message: e.message,
        }));
        validationErrors.push(...errors);
        logger.warn(
          { index: i, errors: errors.map((e) => e.message) },
          'Skipping invalid queue item'
        );
      }
    }

    // If we recovered some valid items, return them
    if (validItems.length > 0) {
      logger.info(
        { validCount: validItems.length, invalidCount: items.length - validItems.length },
        'Partial recovery successful'
      );
      return validItems;
    }

    // No valid items - throw error
    logger.error(
      { totalItems: items.length, errors: validationErrors },
      'No valid queue items in response'
    );
    throw new IntakeValidationError(
      'All items in response failed validation',
      validationErrors
    );
  }

  /**
   * Type guard for the expected response format
   */
  private isIdeasResponse(
    data: unknown
  ): data is { ideas: unknown[]; total: number } {
    return (
      typeof data === 'object' &&
      data !== null &&
      'ideas' in data &&
      Array.isArray((data as Record<string, unknown>).ideas)
    );
  }

  /**
   * Claim an idea from Intake API for processing
   *
   * @param ideaId - UUID of the idea to claim
   * @param claimedBy - Identifier of the claiming orchestrator (e.g., hostname)
   * @returns The claimed idea with all fields including token
   * @throws IdeaAlreadyClaimedError if idea is already claimed (409)
   * @throws IdeaNotFoundError if idea doesn't exist (404)
   * @throws IntakeUnavailableError on network/server errors
   * @throws IntakeAuthError on authentication failure (401/403)
   */
  async claimIdea(ideaId: string, claimedBy: string): Promise<ClaimIdeaResponse> {
    const url = `${this.baseUrl}/api/ideas/${encodeURIComponent(ideaId)}/claim`;

    logger.debug({ ideaId, claimedBy }, 'Claiming idea from Intake API');

    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'X-ORCH-KEY': this.apiKey,
          'Content-Type': 'application/json',
          Accept: 'application/json',
        },
        body: JSON.stringify({ claimedBy }),
        signal: AbortSignal.timeout(this.timeout),
      });

      // Handle HTTP errors
      if (!response.ok) {
        await this.handleClaimError(response, ideaId);
      }

      // Parse successful response
      const json: unknown = await response.json();
      logger.debug({ ideaId }, 'Received claim response from Intake API');

      // Validate response
      const result = ClaimIdeaResponseSchema.safeParse(json);
      if (!result.success) {
        logger.error(
          { ideaId, errors: result.error.errors },
          'Invalid claim response schema'
        );
        throw new IntakeValidationError(
          'Invalid claim response from Intake API',
          result.error.errors.map((e) => ({
            path: e.path.join('.'),
            message: e.message,
          }))
        );
      }

      // Log success with masked token
      logger.info(
        { ideaId, token: `${result.data.token.slice(0, 4)}...` },
        'Successfully claimed idea'
      );

      return result.data;
    } catch (error) {
      // Re-throw our custom errors
      if (
        error instanceof IdeaAlreadyClaimedError ||
        error instanceof IdeaNotFoundError ||
        error instanceof IntakeUnavailableError ||
        error instanceof IntakeNetworkError ||
        error instanceof IntakeAuthError ||
        error instanceof IntakeAPIError ||
        error instanceof IntakeValidationError
      ) {
        throw error;
      }

      // Convert fetch errors to IntakeUnavailableError
      if (error instanceof Error) {
        if (error.name === 'TimeoutError' || error.name === 'AbortError') {
          logger.warn({ ideaId, timeout: this.timeout }, 'Claim request timed out');
          throw new IntakeUnavailableError(
            `Request timed out after ${this.timeout}ms`,
            error
          );
        }

        logger.error({ ideaId, error: error.message }, 'Network error during claim');
        throw new IntakeUnavailableError(`Network error: ${error.message}`, error);
      }

      // Unknown error type
      throw new IntakeUnavailableError('Unknown network error');
    }
  }

  /**
   * Handle error responses from claim endpoint
   */
  private async handleClaimError(response: Response, ideaId: string): Promise<never> {
    const body = await this.safeParseBody(response);

    switch (response.status) {
      case 401:
      case 403:
        logger.warn(
          { status: response.status, ideaId },
          'Authentication failed for claim request'
        );
        throw new IntakeAuthError(
          `Authentication failed: ${response.statusText}`,
          response.status as 401 | 403
        );

      case 404:
        logger.warn({ ideaId }, 'Idea not found');
        throw new IdeaNotFoundError(ideaId);

      case 409:
        logger.warn({ ideaId }, 'Idea already claimed');
        throw new IdeaAlreadyClaimedError(ideaId);

      default:
        if (response.status >= 500) {
          logger.error(
            { status: response.status, ideaId, body },
            'Intake API server error during claim'
          );
          throw new IntakeUnavailableError(
            `Server error: ${response.status} ${response.statusText}`
          );
        }

        logger.error(
          { status: response.status, ideaId, body },
          'Intake API returned unexpected error during claim'
        );
        throw new IntakeAPIError(
          `Intake API error: ${response.status} ${response.statusText}`,
          response.status,
          body
        );
    }
  }
}

